class Article extends DataClass implements Insertable<Article> {
  final int id;
  final String code;
  final String nom;
  final int? categorieId;
  final double prixAchat;
  final double prixVente;

  /// Stock minimum déclenchant une alerte de rupture.
  final double stockMinimum;

  /// Stock total dénormalisé (somme article_stock), recalculé à chaque
  /// mouvement de stock.
  final double stockTotal;
  final DateTime dateCreation;
  final bool actif;

  /// Taux TVA par défaut pré-rempli lors de la saisie d'une ligne (0.0 ou 18.0).
  final double tauxTvaDefaut;

  /// Description libre optionnelle (notes, détails produit...).
  final String? description;
  const Article(
      {required this.id,
      required this.code,
      required this.nom,
      this.categorieId,
      required this.prixAchat,
      required this.prixVente,
      required this.stockMinimum,
      required this.stockTotal,
      required this.dateCreation,
      required this.actif,
      required this.tauxTvaDefaut,
      this.description});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['code'] = Variable<String>(code);
    map['nom'] = Variable<String>(nom);
    if (!nullToAbsent || categorieId != null) {
      map['categorie_id'] = Variable<int>(categorieId);
    }
    map['prix_achat'] = Variable<double>(prixAchat);
    map['prix_vente'] = Variable<double>(prixVente);
    map['stock_minimum'] = Variable<double>(stockMinimum);
    map['stock_total'] = Variable<double>(stockTotal);
    map['date_creation'] = Variable<DateTime>(dateCreation);
    map['actif'] = Variable<bool>(actif);
    map['taux_tva_defaut'] = Variable<double>(tauxTvaDefaut);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    return map;
  }

  ArticlesCompanion toCompanion(bool nullToAbsent) {
    return ArticlesCompanion(
      id: Value(id),
      code: Value(code),
      nom: Value(nom),
      categorieId: categorieId == null && nullToAbsent
          ? const Value.absent()
          : Value(categorieId),
      prixAchat: Value(prixAchat),
      prixVente: Value(prixVente),
      stockMinimum: Value(stockMinimum),
      stockTotal: Value(stockTotal),
      dateCreation: Value(dateCreation),
      actif: Value(actif),
      tauxTvaDefaut: Value(tauxTvaDefaut),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
    );
  }

  factory Article.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Article(
      id: serializer.fromJson<int>(json['id']),
      code: serializer.fromJson<String>(json['code']),
      nom: serializer.fromJson<String>(json['nom']),
      categorieId: serializer.fromJson<int?>(json['categorieId']),
      prixAchat: serializer.fromJson<double>(json['prixAchat']),
      prixVente: serializer.fromJson<double>(json['prixVente']),
      stockMinimum: serializer.fromJson<double>(json['stockMinimum']),
      stockTotal: serializer.fromJson<double>(json['stockTotal']),
      dateCreation: serializer.fromJson<DateTime>(json['dateCreation']),
      actif: serializer.fromJson<bool>(json['actif']),
      tauxTvaDefaut: serializer.fromJson<double>(json['tauxTvaDefaut']),
      description: serializer.fromJson<String?>(json['description']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'code': serializer.toJson<String>(code),
      'nom': serializer.toJson<String>(nom),
      'categorieId': serializer.toJson<int?>(categorieId),
      'prixAchat': serializer.toJson<double>(prixAchat),
      'prixVente': serializer.toJson<double>(prixVente),
      'stockMinimum': serializer.toJson<double>(stockMinimum),
      'stockTotal': serializer.toJson<double>(stockTotal),
      'dateCreation': serializer.toJson<DateTime>(dateCreation),
      'actif': serializer.toJson<bool>(actif),
      'tauxTvaDefaut': serializer.toJson<double>(tauxTvaDefaut),
      'description': serializer.toJson<String?>(description),
    };
  }

  Article copyWith(
          {int? id,
          String? code,
          String? nom,
          Value<int?> categorieId = const Value.absent(),
          double? prixAchat,
          double? prixVente,
          double? stockMinimum,
          double? stockTotal,
          DateTime? dateCreation,
          bool? actif,
          double? tauxTvaDefaut,
          Value<String?> description = const Value.absent()}) =>
      Article(
        id: id ?? this.id,
        code: code ?? this.code,
        nom: nom ?? this.nom,
        categorieId: categorieId.present ? categorieId.value : this.categorieId,
        prixAchat: prixAchat ?? this.prixAchat,
        prixVente: prixVente ?? this.prixVente,
        stockMinimum: stockMinimum ?? this.stockMinimum,
        stockTotal: stockTotal ?? this.stockTotal,
        dateCreation: dateCreation ?? this.dateCreation,
        actif: actif ?? this.actif,
        tauxTvaDefaut: tauxTvaDefaut ?? this.tauxTvaDefaut,
        description: description.present ? description.value : this.description,
      );
  Article copyWithCompanion(ArticlesCompanion data) {
    return Article(
      id: data.id.present ? data.id.value : this.id,
      code: data.code.present ? data.code.value : this.code,
      nom: data.nom.present ? data.nom.value : this.nom,
      categorieId:
          data.categorieId.present ? data.categorieId.value : this.categorieId,
      prixAchat: data.prixAchat.present ? data.prixAchat.value : this.prixAchat,
      prixVente: data.prixVente.present ? data.prixVente.value : this.prixVente,
      stockMinimum: data.stockMinimum.present
          ? data.stockMinimum.value
          : this.stockMinimum,
      stockTotal:
          data.stockTotal.present ? data.stockTotal.value : this.stockTotal,
      dateCreation: data.dateCreation.present
          ? data.dateCreation.value
          : this.dateCreation,
      actif: data.actif.present ? data.actif.value : this.actif,
      tauxTvaDefaut: data.tauxTvaDefaut.present
          ? data.tauxTvaDefaut.value
          : this.tauxTvaDefaut,
      description:
          data.description.present ? data.description.value : this.description,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Article(')
          ..write('id: $id, ')
          ..write('code: $code, ')
          ..write('nom: $nom, ')
          ..write('categorieId: $categorieId, ')
          ..write('prixAchat: $prixAchat, ')
          ..write('prixVente: $prixVente, ')
          ..write('stockMinimum: $stockMinimum, ')
          ..write('stockTotal: $stockTotal, ')
          ..write('dateCreation: $dateCreation, ')
          ..write('actif: $actif, ')
          ..write('tauxTvaDefaut: $tauxTvaDefaut, ')
          ..write('description: $description')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
      id,
      code,
      nom,
      categorieId,
      prixAchat,
      prixVente,
      stockMinimum,
      stockTotal,
      dateCreation,
      actif,
      tauxTvaDefaut,
      description);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Article &&
          other.id == this.id &&
          other.code == this.code &&
          other.nom == this.nom &&
          other.categorieId == this.categorieId &&
          other.prixAchat == this.prixAchat &&
          other.prixVente == this.prixVente &&
          other.stockMinimum == this.stockMinimum &&
          other.stockTotal == this.stockTotal &&
          other.dateCreation == this.dateCreation &&
          other.actif == this.actif &&
          other.tauxTvaDefaut == this.tauxTvaDefaut &&
          other.description == this.description);
}

