class Client extends DataClass implements Insertable<Client> {
  final int id;
  final String nom;
  final String? telephone;
  final String? adresse;
  final double detteTotale;
  final DateTime dateCreation;

  /// Indique si la TVA s'applique aux ventes à ce client (1 = oui, 0 = exonéré).
  final int tvaApplicable;

  /// Délai de paiement accordé, en jours (ex: 30, 60). NULL = comptant.
  final int? delaiPaiementJours;

  /// Conditions textuelles, ex: '30 jours fin de mois'.
  final String? conditionsReglement;

  /// Numéro d'Identification Fiscale du client (entreprise/professionnel).
  /// Affiché sur les factures PDF quand renseigné.
  final String? nif;
  const Client(
      {required this.id,
      required this.nom,
      this.telephone,
      this.adresse,
      required this.detteTotale,
      required this.dateCreation,
      required this.tvaApplicable,
      this.delaiPaiementJours,
      this.conditionsReglement,
      this.nif});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['nom'] = Variable<String>(nom);
    if (!nullToAbsent || telephone != null) {
      map['telephone'] = Variable<String>(telephone);
    }
    if (!nullToAbsent || adresse != null) {
      map['adresse'] = Variable<String>(adresse);
    }
    map['dette_totale'] = Variable<double>(detteTotale);
    map['date_creation'] = Variable<DateTime>(dateCreation);
    map['tva_applicable'] = Variable<int>(tvaApplicable);
    if (!nullToAbsent || delaiPaiementJours != null) {
      map['delai_paiement_jours'] = Variable<int>(delaiPaiementJours);
    }
    if (!nullToAbsent || conditionsReglement != null) {
      map['conditions_reglement'] = Variable<String>(conditionsReglement);
    }
    if (!nullToAbsent || nif != null) {
      map['nif'] = Variable<String>(nif);
    }
    return map;
  }

  ClientsCompanion toCompanion(bool nullToAbsent) {
    return ClientsCompanion(
      id: Value(id),
      nom: Value(nom),
      telephone: telephone == null && nullToAbsent
          ? const Value.absent()
          : Value(telephone),
      adresse: adresse == null && nullToAbsent
          ? const Value.absent()
          : Value(adresse),
      detteTotale: Value(detteTotale),
      dateCreation: Value(dateCreation),
      tvaApplicable: Value(tvaApplicable),
      delaiPaiementJours: delaiPaiementJours == null && nullToAbsent
          ? const Value.absent()
          : Value(delaiPaiementJours),
      conditionsReglement: conditionsReglement == null && nullToAbsent
          ? const Value.absent()
          : Value(conditionsReglement),
      nif: nif == null && nullToAbsent ? const Value.absent() : Value(nif),
    );
