    return (StringBuffer('Supplier(')
          ..write('id: $id, ')
          ..write('nom: $nom, ')
          ..write('telephone: $telephone, ')
          ..write('adresse: $adresse, ')
          ..write('dateCreation: $dateCreation')
          ..write(')'))
        .toString();
