    }
    if (remisePourcentage.present) {
      map['remise_pourcentage'] = Variable<double>(remisePourcentage.value);
    }
    if (remiseMontant.present) {
      map['remise_montant'] = Variable<double>(remiseMontant.value);
    }
    if (totalLigne.present) {
      map['total_ligne'] = Variable<double>(totalLigne.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('QuoteItemsCompanion(')
          ..write('id: $id, ')
          ..write('quoteId: $quoteId, ')
          ..write('articleId: $articleId, ')
          ..write('quantite: $quantite, ')
          ..write('prixUnitaire: $prixUnitaire, ')
          ..write('remisePourcentage: $remisePourcentage, ')
          ..write('remiseMontant: $remiseMontant, ')
          ..write('totalLigne: $totalLigne')
          ..write(')'))
        .toString();
  }
}

