class Invoice extends DataClass implements Insertable<Invoice> {
  final int id;

  /// Numéro affiché, ex: FAC-2026-0001.
  final String numero;

  /// NULL = vente au comptoir sans client enregistré.
  final int? clientId;
  final int storeId;

  /// Renseigné si la facture provient d'un devis converti.
  final int? quoteId;
  final int userId;
  final DateTime dateCreation;
  final double totalHt;
  final double remiseGlobale;
  final double totalFinal;
  final double montantPaye;

  /// 'paye' | 'partiel' | 'non_paye'
  final String statutPaiement;
  final DateTime? dateModification;
  final int? modifieParUserId;
  const Invoice(
      {required this.id,
      required this.numero,
      this.clientId,
      required this.storeId,
      this.quoteId,
      required this.userId,
      required this.dateCreation,
      required this.totalHt,
      required this.remiseGlobale,
      required this.totalFinal,
      required this.montantPaye,
      required this.statutPaiement,
      this.dateModification,
      this.modifieParUserId});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['numero'] = Variable<String>(numero);
    if (!nullToAbsent || clientId != null) {
      map['client_id'] = Variable<int>(clientId);
    }
    map['store_id'] = Variable<int>(storeId);
    if (!nullToAbsent || quoteId != null) {
      map['quote_id'] = Variable<int>(quoteId);
    }
    map['user_id'] = Variable<int>(userId);
    map['date_creation'] = Variable<DateTime>(dateCreation);
    map['total_ht'] = Variable<double>(totalHt);
    map['remise_globale'] = Variable<double>(remiseGlobale);
    map['total_final'] = Variable<double>(totalFinal);
    map['montant_paye'] = Variable<double>(montantPaye);
    map['statut_paiement'] = Variable<String>(statutPaiement);
    if (!nullToAbsent || dateModification != null) {
      map['date_modification'] = Variable<DateTime>(dateModification);
    }
    if (!nullToAbsent || modifieParUserId != null) {
      map['modifie_par_user_id'] = Variable<int>(modifieParUserId);
    }
    return map;
  }

  InvoicesCompanion toCompanion(bool nullToAbsent) {
    return InvoicesCompanion(
      id: Value(id),
      numero: Value(numero),
      clientId: clientId == null && nullToAbsent
          ? const Value.absent()
          : Value(clientId),
      storeId: Value(storeId),
      quoteId: quoteId == null && nullToAbsent
          ? const Value.absent()
          : Value(quoteId),
      userId: Value(userId),
      dateCreation: Value(dateCreation),
      totalHt: Value(totalHt),
      remiseGlobale: Value(remiseGlobale),
      totalFinal: Value(totalFinal),
      montantPaye: Value(montantPaye),
      statutPaiement: Value(statutPaiement),
      dateModification: dateModification == null && nullToAbsent
          ? const Value.absent()
          : Value(dateModification),
      modifieParUserId: modifieParUserId == null && nullToAbsent
          ? const Value.absent()
          : Value(modifieParUserId),
    );
  }

  factory Invoice.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Invoice(
      id: serializer.fromJson<int>(json['id']),
      numero: serializer.fromJson<String>(json['numero']),
      clientId: serializer.fromJson<int?>(json['clientId']),
      storeId: serializer.fromJson<int>(json['storeId']),
      quoteId: serializer.fromJson<int?>(json['quoteId']),
      userId: serializer.fromJson<int>(json['userId']),
      dateCreation: serializer.fromJson<DateTime>(json['dateCreation']),
      totalHt: serializer.fromJson<double>(json['totalHt']),
      remiseGlobale: serializer.fromJson<double>(json['remiseGlobale']),
      totalFinal: serializer.fromJson<double>(json['totalFinal']),
      montantPaye: serializer.fromJson<double>(json['montantPaye']),
      statutPaiement: serializer.fromJson<String>(json['statutPaiement']),
      dateModification:
          serializer.fromJson<DateTime?>(json['dateModification']),
      modifieParUserId: serializer.fromJson<int?>(json['modifieParUserId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'numero': serializer.toJson<String>(numero),
      'clientId': serializer.toJson<int?>(clientId),
      'storeId': serializer.toJson<int>(storeId),
      'quoteId': serializer.toJson<int?>(quoteId),
      'userId': serializer.toJson<int>(userId),
      'dateCreation': serializer.toJson<DateTime>(dateCreation),
      'totalHt': serializer.toJson<double>(totalHt),
      'remiseGlobale': serializer.toJson<double>(remiseGlobale),
      'totalFinal': serializer.toJson<double>(totalFinal),
      'montantPaye': serializer.toJson<double>(montantPaye),
      'statutPaiement': serializer.toJson<String>(statutPaiement),
      'dateModification': serializer.toJson<DateTime?>(dateModification),
      'modifieParUserId': serializer.toJson<int?>(modifieParUserId),
    };
  }

  Invoice copyWith(
          {int? id,
          String? numero,
          Value<int?> clientId = const Value.absent(),
          int? storeId,
          Value<int?> quoteId = const Value.absent(),
          int? userId,
          DateTime? dateCreation,
          double? totalHt,
          double? remiseGlobale,
          double? totalFinal,
          double? montantPaye,
          String? statutPaiement,
          Value<DateTime?> dateModification = const Value.absent(),
          Value<int?> modifieParUserId = const Value.absent()}) =>
      Invoice(
        id: id ?? this.id,
        numero: numero ?? this.numero,
        clientId: clientId.present ? clientId.value : this.clientId,
        storeId: storeId ?? this.storeId,
        quoteId: quoteId.present ? quoteId.value : this.quoteId,
        userId: userId ?? this.userId,
        dateCreation: dateCreation ?? this.dateCreation,
        totalHt: totalHt ?? this.totalHt,
        remiseGlobale: remiseGlobale ?? this.remiseGlobale,
        totalFinal: totalFinal ?? this.totalFinal,
        montantPaye: montantPaye ?? this.montantPaye,
        statutPaiement: statutPaiement ?? this.statutPaiement,
        dateModification: dateModification.present
            ? dateModification.value
            : this.dateModification,
        modifieParUserId: modifieParUserId.present
            ? modifieParUserId.value
            : this.modifieParUserId,
      );
  Invoice copyWithCompanion(InvoicesCompanion data) {
    return Invoice(
      id: data.id.present ? data.id.value : this.id,
      numero: data.numero.present ? data.numero.value : this.numero,
      clientId: data.clientId.present ? data.clientId.value : this.clientId,
      storeId: data.storeId.present ? data.storeId.value : this.storeId,
      quoteId: data.quoteId.present ? data.quoteId.value : this.quoteId,
      userId: data.userId.present ? data.userId.value : this.userId,
      dateCreation: data.dateCreation.present
          ? data.dateCreation.value
          : this.dateCreation,
      totalHt: data.totalHt.present ? data.totalHt.value : this.totalHt,
      remiseGlobale: data.remiseGlobale.present
          ? data.remiseGlobale.value
          : this.remiseGlobale,
      totalFinal:
          data.totalFinal.present ? data.totalFinal.value : this.totalFinal,
      montantPaye:
          data.montantPaye.present ? data.montantPaye.value : this.montantPaye,
      statutPaiement: data.statutPaiement.present
          ? data.statutPaiement.value
          : this.statutPaiement,
      dateModification: data.dateModification.present
          ? data.dateModification.value
          : this.dateModification,
      modifieParUserId: data.modifieParUserId.present
          ? data.modifieParUserId.value
          : this.modifieParUserId,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Invoice(')
          ..write('id: $id, ')
          ..write('numero: $numero, ')
          ..write('clientId: $clientId, ')
          ..write('storeId: $storeId, ')
          ..write('quoteId: $quoteId, ')
          ..write('userId: $userId, ')
          ..write('dateCreation: $dateCreation, ')
          ..write('totalHt: $totalHt, ')
          ..write('remiseGlobale: $remiseGlobale, ')
          ..write('totalFinal: $totalFinal, ')
          ..write('montantPaye: $montantPaye, ')
          ..write('statutPaiement: $statutPaiement, ')
          ..write('dateModification: $dateModification, ')
          ..write('modifieParUserId: $modifieParUserId')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
      id,
      numero,
      clientId,
      storeId,
      quoteId,
      userId,
      dateCreation,
      totalHt,
      remiseGlobale,
      totalFinal,
      montantPaye,
      statutPaiement,
      dateModification,
      modifieParUserId);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Invoice &&
          other.id == this.id &&
          other.numero == this.numero &&
          other.clientId == this.clientId &&
          other.storeId == this.storeId &&
          other.quoteId == this.quoteId &&
          other.userId == this.userId &&
          other.dateCreation == this.dateCreation &&
          other.totalHt == this.totalHt &&
          other.remiseGlobale == this.remiseGlobale &&
          other.totalFinal == this.totalFinal &&
          other.montantPaye == this.montantPaye &&
          other.statutPaiement == this.statutPaiement &&
          other.dateModification == this.dateModification &&
          other.modifieParUserId == this.modifieParUserId);
}

