    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['article_id'] = Variable<int>(articleId);
    map['store_id'] = Variable<int>(storeId);
    map['type_mouvement'] = Variable<String>(typeMouvement);
    map['quantite'] = Variable<double>(quantite);
    if (!nullToAbsent || reference != null) {
      map['reference'] = Variable<String>(reference);
    }
    if (!nullToAbsent || groupeId != null) {
      map['groupe_id'] = Variable<String>(groupeId);
    }
    map['date_mouvement'] = Variable<DateTime>(dateMouvement);
    map['user_id'] = Variable<int>(userId);
    return map;
  }

  StockMovementsCompanion toCompanion(bool nullToAbsent) {
    return StockMovementsCompanion(
      id: Value(id),
      articleId: Value(articleId),
      storeId: Value(storeId),
      typeMouvement: Value(typeMouvement),
      quantite: Value(quantite),
      reference: reference == null && nullToAbsent
          ? const Value.absent()
          : Value(reference),
      groupeId: groupeId == null && nullToAbsent
