      storeFromId: storeFromId ?? this.storeFromId,
      storeToId: storeToId ?? this.storeToId,
      quantite: quantite ?? this.quantite,
      dateTransfert: dateTransfert ?? this.dateTransfert,
      userId: userId ?? this.userId,
      statut: statut ?? this.statut,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<int>(id.value);
    }
    if (articleId.present) {
      map['article_id'] = Variable<int>(articleId.value);
    }
    if (storeFromId.present) {
      map['store_from_id'] = Variable<int>(storeFromId.value);
    }
    if (storeToId.present) {
      map['store_to_id'] = Variable<int>(storeToId.value);
    }
    if (quantite.present) {
      map['quantite'] = Variable<double>(quantite.value);
    }
    if (dateTransfert.present) {
      map['date_transfert'] = Variable<DateTime>(dateTransfert.value);
    }
    if (userId.present) {
      map['user_id'] = Variable<int>(userId.value);
    }
    if (statut.present) {
      map['statut'] = Variable<String>(statut.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('StockTransfersCompanion(')
          ..write('id: $id, ')
          ..write('articleId: $articleId, ')
          ..write('storeFromId: $storeFromId, ')
          ..write('storeToId: $storeToId, ')
          ..write('quantite: $quantite, ')
          ..write('dateTransfert: $dateTransfert, ')
          ..write('userId: $userId, ')
          ..write('statut: $statut')
          ..write(')'))
        .toString();
  }
}

