class Inventory extends DataClass implements Insertable<Inventory> {
  final int id;

  /// Numéro séquentiel, ex: "INV-2026-0001".
  final String numero;
  final int storeId;
  final int? categorieId;

  /// 'brouillon' (comptage en cours) | 'valide' (verrouillé, stock
  /// mis à jour) | 'annule'.
  final String statut;
  final DateTime dateCreation;
  final DateTime? dateValidation;
  final int createdByUserId;
  final int? validatedByUserId;
  final int nbArticles;
  final int nbSansEcart;
  final int nbAvecEcart;
  final int nbIntrouvables;
  final String? observation;
  const Inventory(
      {required this.id,
      required this.numero,
      required this.storeId,
      this.categorieId,
      required this.statut,
      required this.dateCreation,
      this.dateValidation,
      required this.createdByUserId,
      this.validatedByUserId,
      required this.nbArticles,
      required this.nbSansEcart,
      required this.nbAvecEcart,
      required this.nbIntrouvables,
      this.observation});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['numero'] = Variable<String>(numero);
    map['store_id'] = Variable<int>(storeId);
    if (!nullToAbsent || categorieId != null) {
      map['categorie_id'] = Variable<int>(categorieId);
    }
    map['statut'] = Variable<String>(statut);
    map['date_creation'] = Variable<DateTime>(dateCreation);
    if (!nullToAbsent || dateValidation != null) {
      map['date_validation'] = Variable<DateTime>(dateValidation);
    }
    map['created_by_user_id'] = Variable<int>(createdByUserId);
    if (!nullToAbsent || validatedByUserId != null) {
      map['validated_by_user_id'] = Variable<int>(validatedByUserId);
    }
    map['nb_articles'] = Variable<int>(nbArticles);
    map['nb_sans_ecart'] = Variable<int>(nbSansEcart);
    map['nb_avec_ecart'] = Variable<int>(nbAvecEcart);
    map['nb_introuvables'] = Variable<int>(nbIntrouvables);
    if (!nullToAbsent || observation != null) {
      map['observation'] = Variable<String>(observation);
    }
    return map;
  }

  InventoriesCompanion toCompanion(bool nullToAbsent) {
    return InventoriesCompanion(
      id: Value(id),
      numero: Value(numero),
      storeId: Value(storeId),
      categorieId: categorieId == null && nullToAbsent
          ? const Value.absent()
          : Value(categorieId),
      statut: Value(statut),
      dateCreation: Value(dateCreation),
      dateValidation: dateValidation == null && nullToAbsent
          ? const Value.absent()
          : Value(dateValidation),
      createdByUserId: Value(createdByUserId),
      validatedByUserId: validatedByUserId == null && nullToAbsent
          ? const Value.absent()
          : Value(validatedByUserId),
      nbArticles: Value(nbArticles),
      nbSansEcart: Value(nbSansEcart),
      nbAvecEcart: Value(nbAvecEcart),
      nbIntrouvables: Value(nbIntrouvables),
      observation: observation == null && nullToAbsent
          ? const Value.absent()
          : Value(observation),
    );
  }

  factory Inventory.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Inventory(
      id: serializer.fromJson<int>(json['id']),
      numero: serializer.fromJson<String>(json['numero']),
      storeId: serializer.fromJson<int>(json['storeId']),
      categorieId: serializer.fromJson<int?>(json['categorieId']),
      statut: serializer.fromJson<String>(json['statut']),
      dateCreation: serializer.fromJson<DateTime>(json['dateCreation']),
      dateValidation: serializer.fromJson<DateTime?>(json['dateValidation']),
      createdByUserId: serializer.fromJson<int>(json['createdByUserId']),
      validatedByUserId: serializer.fromJson<int?>(json['validatedByUserId']),
      nbArticles: serializer.fromJson<int>(json['nbArticles']),
      nbSansEcart: serializer.fromJson<int>(json['nbSansEcart']),
      nbAvecEcart: serializer.fromJson<int>(json['nbAvecEcart']),
      nbIntrouvables: serializer.fromJson<int>(json['nbIntrouvables']),
      observation: serializer.fromJson<String?>(json['observation']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'numero': serializer.toJson<String>(numero),
      'storeId': serializer.toJson<int>(storeId),
      'categorieId': serializer.toJson<int?>(categorieId),
      'statut': serializer.toJson<String>(statut),
      'dateCreation': serializer.toJson<DateTime>(dateCreation),
      'dateValidation': serializer.toJson<DateTime?>(dateValidation),
      'createdByUserId': serializer.toJson<int>(createdByUserId),
      'validatedByUserId': serializer.toJson<int?>(validatedByUserId),
      'nbArticles': serializer.toJson<int>(nbArticles),
      'nbSansEcart': serializer.toJson<int>(nbSansEcart),
      'nbAvecEcart': serializer.toJson<int>(nbAvecEcart),
      'nbIntrouvables': serializer.toJson<int>(nbIntrouvables),
      'observation': serializer.toJson<String?>(observation),
    };
  }

  Inventory copyWith(
          {int? id,
          String? numero,
          int? storeId,
          Value<int?> categorieId = const Value.absent(),
          String? statut,
          DateTime? dateCreation,
          Value<DateTime?> dateValidation = const Value.absent(),
          int? createdByUserId,
          Value<int?> validatedByUserId = const Value.absent(),
