        createdByUserId: createdByUserId ?? this.createdByUserId,
        validatedByUserId: validatedByUserId.present
            ? validatedByUserId.value
            : this.validatedByUserId,
        nbArticles: nbArticles ?? this.nbArticles,
        nbSansEcart: nbSansEcart ?? this.nbSansEcart,
        nbAvecEcart: nbAvecEcart ?? this.nbAvecEcart,
        nbIntrouvables: nbIntrouvables ?? this.nbIntrouvables,
        observation: observation.present ? observation.value : this.observation,
      );
  Inventory copyWithCompanion(InventoriesCompanion data) {
    return Inventory(
      id: data.id.present ? data.id.value : this.id,
      numero: data.numero.present ? data.numero.value : this.numero,
      storeId: data.storeId.present ? data.storeId.value : this.storeId,
      categorieId:
          data.categorieId.present ? data.categorieId.value : this.categorieId,
      statut: data.statut.present ? data.statut.value : this.statut,
      dateCreation: data.dateCreation.present
          ? data.dateCreation.value
          : this.dateCreation,
      dateValidation: data.dateValidation.present
          ? data.dateValidation.value
          : this.dateValidation,
      createdByUserId: data.createdByUserId.present
          ? data.createdByUserId.value
          : this.createdByUserId,
      validatedByUserId: data.validatedByUserId.present
          ? data.validatedByUserId.value
          : this.validatedByUserId,
      nbArticles:
          data.nbArticles.present ? data.nbArticles.value : this.nbArticles,
      nbSansEcart:
          data.nbSansEcart.present ? data.nbSansEcart.value : this.nbSansEcart,
      nbAvecEcart:
          data.nbAvecEcart.present ? data.nbAvecEcart.value : this.nbAvecEcart,
      nbIntrouvables: data.nbIntrouvables.present
          ? data.nbIntrouvables.value
          : this.nbIntrouvables,
      observation:
          data.observation.present ? data.observation.value : this.observation,
    );
