          ..write('nbSansEcart: $nbSansEcart, ')
          ..write('nbAvecEcart: $nbAvecEcart, ')
          ..write('nbIntrouvables: $nbIntrouvables, ')
          ..write('observation: $observation')
          ..write(')'))
        .toString();
  }
}

