class InventoryLine extends DataClass implements Insertable<InventoryLine> {
  final int id;
  final int inventoryId;

  /// Null si le code lu à l'import ne correspond à aucun article
  /// connu (voir [introuvable]).
  final int? articleId;
  final String articleCode;
  final String articleNom;
  final String? categorieNom;
  final double stockTheorique;

  /// Null tant que la ligne n'a pas été comptée (ni import, ni saisie
  /// manuelle).
  final double? stockPhysique;

  /// stockPhysique - stockTheorique. Null tant que non compté.
  final double? ecart;
  final String? observation;

  /// Vrai si cette ligne provient d'un import dont le code ne
  /// correspondait à aucun article du catalogue.
  final bool introuvable;
  const InventoryLine(
      {required this.id,
      required this.inventoryId,
      this.articleId,
      required this.articleCode,
      required this.articleNom,
      this.categorieNom,
      required this.stockTheorique,
      this.stockPhysique,
      this.ecart,
      this.observation,
      required this.introuvable});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['inventory_id'] = Variable<int>(inventoryId);
    if (!nullToAbsent || articleId != null) {
      map['article_id'] = Variable<int>(articleId);
    }
    map['article_code'] = Variable<String>(articleCode);
    map['article_nom'] = Variable<String>(articleNom);
    if (!nullToAbsent || categorieNom != null) {
      map['categorie_nom'] = Variable<String>(categorieNom);
    }
    map['stock_theorique'] = Variable<double>(stockTheorique);
    if (!nullToAbsent || stockPhysique != null) {
      map['stock_physique'] = Variable<double>(stockPhysique);
    }
    if (!nullToAbsent || ecart != null) {
      map['ecart'] = Variable<double>(ecart);
    }
    if (!nullToAbsent || observation != null) {
      map['observation'] = Variable<String>(observation);
    }
    map['introuvable'] = Variable<bool>(introuvable);
    return map;
  }

  InventoryLinesCompanion toCompanion(bool nullToAbsent) {
    return InventoryLinesCompanion(
      id: Value(id),
      inventoryId: Value(inventoryId),
      articleId: articleId == null && nullToAbsent
          ? const Value.absent()
          : Value(articleId),
      articleCode: Value(articleCode),
      articleNom: Value(articleNom),
      categorieNom: categorieNom == null && nullToAbsent
          ? const Value.absent()
          : Value(categorieNom),
      stockTheorique: Value(stockTheorique),
      stockPhysique: stockPhysique == null && nullToAbsent
          ? const Value.absent()
          : Value(stockPhysique),
      ecart:
          ecart == null && nullToAbsent ? const Value.absent() : Value(ecart),
      observation: observation == null && nullToAbsent
          ? const Value.absent()
          : Value(observation),
      introuvable: Value(introuvable),
    );
  }

  factory InventoryLine.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return InventoryLine(
      id: serializer.fromJson<int>(json['id']),
      inventoryId: serializer.fromJson<int>(json['inventoryId']),
      articleId: serializer.fromJson<int?>(json['articleId']),
      articleCode: serializer.fromJson<String>(json['articleCode']),
      articleNom: serializer.fromJson<String>(json['articleNom']),
      categorieNom: serializer.fromJson<String?>(json['categorieNom']),
      stockTheorique: serializer.fromJson<double>(json['stockTheorique']),
      stockPhysique: serializer.fromJson<double?>(json['stockPhysique']),
      ecart: serializer.fromJson<double?>(json['ecart']),
      observation: serializer.fromJson<String?>(json['observation']),
      introuvable: serializer.fromJson<bool>(json['introuvable']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'inventoryId': serializer.toJson<int>(inventoryId),
      'articleId': serializer.toJson<int?>(articleId),
      'articleCode': serializer.toJson<String>(articleCode),
      'articleNom': serializer.toJson<String>(articleNom),
      'categorieNom': serializer.toJson<String?>(categorieNom),
      'stockTheorique': serializer.toJson<double>(stockTheorique),
      'stockPhysique': serializer.toJson<double?>(stockPhysique),
      'ecart': serializer.toJson<double?>(ecart),
      'observation': serializer.toJson<String?>(observation),
      'introuvable': serializer.toJson<bool>(introuvable),
    };
  }

  InventoryLine copyWith(
          {int? id,
          int? inventoryId,
          Value<int?> articleId = const Value.absent(),
          String? articleCode,
          String? articleNom,
          Value<String?> categorieNom = const Value.absent(),
          double? stockTheorique,
          Value<double?> stockPhysique = const Value.absent(),
          Value<double?> ecart = const Value.absent(),
          Value<String?> observation = const Value.absent(),
          bool? introuvable}) =>
      InventoryLine(
        id: id ?? this.id,
        inventoryId: inventoryId ?? this.inventoryId,
        articleId: articleId.present ? articleId.value : this.articleId,
        articleCode: articleCode ?? this.articleCode,
        articleNom: articleNom ?? this.articleNom,
        categorieNom:
            categorieNom.present ? categorieNom.value : this.categorieNom,
        stockTheorique: stockTheorique ?? this.stockTheorique,
        stockPhysique:
            stockPhysique.present ? stockPhysique.value : this.stockPhysique,
        ecart: ecart.present ? ecart.value : this.ecart,
        observation: observation.present ? observation.value : this.observation,
        introuvable: introuvable ?? this.introuvable,
      );
  InventoryLine copyWithCompanion(InventoryLinesCompanion data) {
    return InventoryLine(
      id: data.id.present ? data.id.value : this.id,
      inventoryId:
          data.inventoryId.present ? data.inventoryId.value : this.inventoryId,
      articleId: data.articleId.present ? data.articleId.value : this.articleId,
      articleCode:
          data.articleCode.present ? data.articleCode.value : this.articleCode,
      articleNom:
          data.articleNom.present ? data.articleNom.value : this.articleNom,
      categorieNom: data.categorieNom.present
          ? data.categorieNom.value
          : this.categorieNom,
      stockTheorique: data.stockTheorique.present
          ? data.stockTheorique.value
          : this.stockTheorique,
      stockPhysique: data.stockPhysique.present
          ? data.stockPhysique.value
          : this.stockPhysique,
      ecart: data.ecart.present ? data.ecart.value : this.ecart,
      observation:
          data.observation.present ? data.observation.value : this.observation,
      introuvable:
          data.introuvable.present ? data.introuvable.value : this.introuvable,
    );
  }

  @override
  String toString() {
    return (StringBuffer('InventoryLine(')
          ..write('id: $id, ')
          ..write('inventoryId: $inventoryId, ')
          ..write('articleId: $articleId, ')
          ..write('articleCode: $articleCode, ')
          ..write('articleNom: $articleNom, ')
          ..write('categorieNom: $categorieNom, ')
          ..write('stockTheorique: $stockTheorique, ')
          ..write('stockPhysique: $stockPhysique, ')
          ..write('ecart: $ecart, ')
          ..write('observation: $observation, ')
          ..write('introuvable: $introuvable')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
      id,
      inventoryId,
      articleId,
      articleCode,
      articleNom,
      categorieNom,
      stockTheorique,
      stockPhysique,
      ecart,
      observation,
      introuvable);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is InventoryLine &&
          other.id == this.id &&
          other.inventoryId == this.inventoryId &&
          other.articleId == this.articleId &&
          other.articleCode == this.articleCode &&
          other.articleNom == this.articleNom &&
          other.categorieNom == this.categorieNom &&
          other.stockTheorique == this.stockTheorique &&
          other.stockPhysique == this.stockPhysique &&
          other.ecart == this.ecart &&
          other.observation == this.observation &&
          other.introuvable == this.introuvable);
}

