    (Category, $$CategoriesTableReferences),
    Category,
    PrefetchHooks Function({bool articlesRefs, bool inventoriesRefs})> {
  $$CategoriesTableTableManager(_$AppDatabase db, $CategoriesTable table)
      : super(TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$CategoriesTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$CategoriesTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$CategoriesTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback: ({
            Value<int> id = const Value.absent(),
            Value<String> nom = const Value.absent(),
          }) =>
              CategoriesCompanion(
            id: id,
            nom: nom,
          ),
          createCompanionCallback: ({
            Value<int> id = const Value.absent(),
            required String nom,
          }) =>
              CategoriesCompanion.insert(
            id: id,
            nom: nom,
          ),
          withReferenceMapper: (p0) => p0
              .map((e) => (
                    e.readTable(table),
                    $$CategoriesTableReferences(db, table, e)
                  ))
              .toList(),
          prefetchHooksCallback: (
              {articlesRefs = false, inventoriesRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (articlesRefs) db.articles,
                if (inventoriesRefs) db.inventories
              ],
              addJoins: null,
              getPrefetchedDataCallback: (items) async {
                return [
                  if (articlesRefs)
                    await $_getPrefetchedData<Category, $CategoriesTable,
                            Article>(
                        currentTable: table,
                        referencedTable:
                            $$CategoriesTableReferences._articlesRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$CategoriesTableReferences(db, table, p0)
                                .articlesRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.categorieId == item.id),
                        typedResults: items),
                  if (inventoriesRefs)
                    await $_getPrefetchedData<Category, $CategoriesTable,
                            Inventory>(
                        currentTable: table,
                        referencedTable: $$CategoriesTableReferences
                            ._inventoriesRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$CategoriesTableReferences(db, table, p0)
                                .inventoriesRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.categorieId == item.id),
                        typedResults: items)
                ];
              },
            );
          },
        ));
}

