            modifieParUserId: modifieParUserId,
          ),
          createCompanionCallback: ({
            Value<int> id = const Value.absent(),
            required String numero,
            Value<int?> clientId = const Value.absent(),
            required int storeId,
            Value<int?> quoteId = const Value.absent(),
            required int userId,
            Value<DateTime> dateCreation = const Value.absent(),
            Value<double> totalHt = const Value.absent(),
            Value<double> remiseGlobale = const Value.absent(),
            Value<double> totalFinal = const Value.absent(),
