                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.userId,
                    referencedTable:
                        $$PurchasesTableReferences._userIdTable(db),
                    referencedColumn:
                        $$PurchasesTableReferences._userIdTable(db).id,
                  ) as T;
                }
                if (modifieParUserId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.modifieParUserId,
                    referencedTable:
                        $$PurchasesTableReferences._modifieParUserIdTable(db),
                    referencedColumn: $$PurchasesTableReferences
                        ._modifieParUserIdTable(db)
                        .id,
                  ) as T;
                }

                return state;
              },
              getPrefetchedDataCallback: (items) async {
                return [
                  if (purchaseItemsRefs)
                    await $_getPrefetchedData<Purchase, $PurchasesTable,
                            PurchaseItem>(
                        currentTable: table,
                        referencedTable: $$PurchasesTableReferences
                            ._purchaseItemsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$PurchasesTableReferences(db, table, p0)
                                .purchaseItemsRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.purchaseId == item.id),
                        typedResults: items),
                  if (paymentsRefs)
                    await $_getPrefetchedData<Purchase, $PurchasesTable,
                            Payment>(
                        currentTable: table,
                        referencedTable:
                            $$PurchasesTableReferences._paymentsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$PurchasesTableReferences(db, table, p0)
                                .paymentsRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.purchaseId == item.id),
                        typedResults: items)
