            Value<int> nbArticles = const Value.absent(),
            Value<int> nbSansEcart = const Value.absent(),
            Value<int> nbAvecEcart = const Value.absent(),
            Value<int> nbIntrouvables = const Value.absent(),
            Value<String?> observation = const Value.absent(),
          }) =>
              InventoriesCompanion.insert(
            id: id,
            numero: numero,
            storeId: storeId,
            categorieId: categorieId,
            statut: statut,
            dateCreation: dateCreation,
            dateValidation: dateValidation,
