                    currentTable: table,
                    currentColumn: table.createdByUserId,
                    referencedTable:
                        $$InventoriesTableReferences._createdByUserIdTable(db),
                    referencedColumn: $$InventoriesTableReferences
                        ._createdByUserIdTable(db)
                        .id,
                  ) as T;
                }
                if (validatedByUserId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.validatedByUserId,
                    referencedTable: $$InventoriesTableReferences
                        ._validatedByUserIdTable(db),
